struct D(&'static str); impl Drop for D { fn drop(&mut self) { println!("drop {}", self.0); } }
fn f(p:bool)->u8 {if !p {let _d=D("left"); println!("branch left"); 1u8} else {let _d=D("right"); println!("branch right"); 2u8}}
fn main(){for p in [false,true]{println!("before");println!("{}",f(p));println!("after");}}

